import {Geometry} from './composition-model.mjs';

// A same-origin, separate window; all user text is inserted through textContent.
// Only an explicit Apply commits the draft. The parent validates the source again.
export function createCompositionEditor(win,init,L,onApply){
 const doc=win.document;doc.title=L.cropTitle+' — '+init.title;doc.documentElement.lang=init.language.toLowerCase();doc.body.replaceChildren();
 const css=doc.createElement('style');css.textContent=`*{box-sizing:border-box}body{margin:0;background:#09131b;color:#e6eef2;font:18px/1.5 system-ui,sans-serif}button,input,select{font:inherit;color:inherit;background:#142b36;border:1px solid #577681;border-radius:10px;padding:10px;min-height:46px}button{cursor:pointer}button:hover{border-color:#f1c27f}button:focus-visible,input:focus-visible,select:focus-visible,canvas:focus-visible{outline:3px solid #f1c27f;outline-offset:3px}button:disabled{opacity:.45;cursor:default}input[type=range]{width:100%;accent-color:#f1c27f;padding:0}input[type=checkbox]{min-height:22px;width:23px;height:23px;accent-color:#f1c27f}header{padding:16px 24px;border-bottom:1px solid #38525e}h1{font-size:26px;margin:0}header p{margin:8px 0;color:#b7cbd2;max-width:1100px}.tools{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.layout{display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:20px;padding:20px}.stage{position:sticky;top:16px;align-self:start;min-width:0}#stage{width:100%;height:min(67vh,850px);min-height:320px;background:#02070a;border:1px solid #45616d;border-radius:12px;touch-action:none;display:block}.controls{min-width:0;display:grid;gap:15px}label{display:grid;gap:6px}.check{display:flex;align-items:center;gap:10px}.primary{background:#f1c27f;color:#171e23;font-weight:700}.selected{border:2px solid #f1c27f;color:#f1c27f}#preview{width:100%;height:190px;background:#02070a;border:1px solid #45616d;border-radius:10px}#message{color:#f1c27f;min-height:28px;overflow-wrap:anywhere}.muted{color:#b7cbd2}.actions{background:#09131b;padding:0 0 8px;display:flex;gap:10px;flex-wrap:wrap}output{color:#f1c27f;font-variant-numeric:tabular-nums}@media(max-width:900px){.layout{grid-template-columns:1fr}.stage{position:static}#stage{height:56vh}.controls{grid-template-columns:repeat(2,minmax(0,1fr))}.controls>.tools,.controls>#message,.controls>.actions{grid-column:1/-1}}@media(max-width:540px){body{font-size:17px}.layout{padding:12px}.controls{grid-template-columns:1fr}#stage{min-height:250px}header{padding:12px}}`;
 doc.head.append(css);
 const make=(tag,text,parent)=>{const n=doc.createElement(tag);if(text!==undefined)n.textContent=text;parent?.append(n);return n;};
 const head=make('header',undefined,doc.body);make('h1',L.cropTitle+' · '+init.title,head);make('p',L.cropHelp,head);
 const layout=make('main',undefined,doc.body);layout.className='layout';const stage=make('section',undefined,layout);stage.className='stage';const toolbar=make('div',undefined,stage);toolbar.className='tools';
 const btn=(text,fn,parent=toolbar,id)=>{const b=make('button',text,parent);b.type='button';b.onclick=fn;if(id)b.id=id;return b;};
 let plan=null,img=null,active='start',mode='move',drag=null,playing=false,started=0,frame=0,loading=0,closed=false;
 const start=btn(L.cropStart,()=>{active='start';stop();sync();},toolbar,'startFrame'),end=btn(L.cropEnd,()=>{active='end';stop();sync();},toolbar,'endFrame');
 const move=btn(L.cropMove,()=>{mode='move';sync();},toolbar,'moveMode'),focus=btn(L.cropFocus,()=>{mode='focus';sync();},toolbar,'focusMode');
 const canvas=make('canvas',undefined,stage);canvas.id='stage';canvas.tabIndex=0;canvas.setAttribute('aria-label',L.cropHelp);
 make('p',L.cropView,stage).className='muted';const progress=make('output','',stage);progress.id='frameProgress';
 const controls=make('aside',undefined,layout);controls.className='controls';
 const sourceLabel=make('label',L.cropSource,controls),source=make('select',undefined,sourceLabel);source.id='source';for(const item of init.images){const o=make('option',item.source==='reference'?L.cropReference:L.cropResult,source);o.value=item.source;}
 function check(text,id,checked,change){const l=make('label',undefined,controls);l.className='check';const input=make('input',undefined,l);input.type='checkbox';input.id=id;input.checked=checked;input.onchange=change;make('span',text,l);return input;}
 const enabled=check(L.cropEnabled,'enabled',true,()=>{if(plan)plan.enabled=enabled.checked;}),motion=check(L.cropMotion,'motion',false,()=>{if(!plan)return;stop();plan.motion=motion.checked;if(!plan.motion)active='start';sync();}),grid=check(L.cropGrid,'grid',true,()=>draw());
 function range(text,id,min,max,step,fn){const l=make('label',text,controls),input=make('input',undefined,l),out=make('output','',l);input.type='range';input.id=id;input.min=min;input.max=max;input.step=step;input.oninput=()=>{if(!plan)return;stop();fn(Number(input.value));sync();};return {input,out};}
 const zoom=range(L.cropZoom,'zoom',1,10,.01,v=>{plan[active]=Geometry.zoom(plan[active],(Geometry.fit(plan.sourceRatio,plan.aspect).w/plan[active].w)/v,plan.sourceRatio,plan.aspect);});
 const x=range(L.cropX,'centreX',0,100,.1,v=>{plan[active]=Geometry.move(plan[active],v/100-Geometry.centre(plan[active]).x,0);}),y=range(L.cropY,'centreY',0,100,.1,v=>{plan[active]=Geometry.move(plan[active],0,v/100-Geometry.centre(plan[active]).y);});
 const tools=make('div',undefined,controls);tools.className='tools';const copy=btn(L.cropCopy,()=>{if(!plan)return;stop();plan.end={...plan.start};sync();},tools,'copyStart');btn(L.cropSuggested,()=>{if(!img)return;stop();plan=defaultPlan(source.value);active='start';sync();},tools,'suggested');
 const preview=make('canvas',undefined,controls);preview.id='preview';preview.setAttribute('aria-label',L.cropView);const play=btn(L.cropPlay,()=>{if(!plan)return;if(playing){stop();return;}playing=true;started=win.performance.now();play.textContent=L.cropStop;tick();},controls,'playPreview');
 const message=make('p',init.stale?L.compositionStale:'',controls);message.id='message';message.setAttribute('role','status');
 const actions=make('div',undefined,controls);actions.className='actions';const apply=btn(L.cropApply,()=>{try{const checked=Geometry.validate(plan),error=onApply(checked);if(error){message.textContent=error;return;}win.close();}catch{message.textContent=L.cropChanged;}},actions,'apply');apply.className='primary';btn(L.cropCancel,()=>win.close(),actions,'cancel');controls.prepend(actions);
 function currentImage(){return init.images.find(i=>i.source===source.value);}
 function defaultPlan(kind){const item=init.images.find(i=>i.source===kind);return Geometry.defaults({sourceRatio:img.naturalWidth/img.naturalHeight,aspect:init.aspect,framing:init.framing,camera:init.camera,source:kind,sourceKey:item.key});}
 async function load(){const serial=++loading;stop();apply.disabled=true;canvas.style.opacity='.4';const loaded=new win.Image();loaded.src=currentImage().data;try{await loaded.decode();if(closed||serial!==loading)return;img=loaded;const old=init.plan;plan=old&&old.source===source.value&&old.sourceKey===currentImage().key&&old.aspect===init.aspect?Geometry.validate(old):defaultPlan(source.value);active='start';canvas.style.opacity='1';apply.disabled=false;sync();}catch{message.textContent=L.cropChanged;}}
 source.onchange=()=>void load();source.value=init.plan&&init.images.some(i=>i.source===init.plan.source)?init.plan.source:init.images[0].source;
 function surface(c){const box=c.getBoundingClientRect(),dpr=Math.min(win.devicePixelRatio||1,2),w=Math.max(1,Math.round(box.width*dpr)),h=Math.max(1,Math.round(box.height*dpr));if(c.width!==w)c.width=w;if(c.height!==h)c.height=h;const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);return {ctx,w:box.width,h:box.height};}
 function imageBox(w,h){const scale=Math.min(w/img.naturalWidth,h/img.naturalHeight);return {x:(w-img.naturalWidth*scale)/2,y:(h-img.naturalHeight*scale)/2,w:img.naturalWidth*scale,h:img.naturalHeight*scale};}
 function draw(){if(!img||!plan||closed)return;const {ctx,w,h}=surface(canvas),box=imageBox(w,h);ctx.clearRect(0,0,w,h);ctx.drawImage(img,box.x,box.y,box.w,box.h);const r=plan[active],sx=box.x+r.x*box.w,sy=box.y+r.y*box.h,rw=r.w*box.w,rh=r.h*box.h;ctx.fillStyle='#0009';ctx.beginPath();ctx.rect(box.x,box.y,box.w,box.h);ctx.rect(sx+rw,sy,-rw,rh);ctx.fill('evenodd');
  function outline(rect,color,dashed=false){ctx.strokeStyle=color;ctx.lineWidth=2;ctx.setLineDash(dashed?[7,5]:[]);ctx.strokeRect(box.x+rect.x*box.w,box.y+rect.y*box.h,rect.w*box.w,rect.h*box.h);ctx.setLineDash([]);}
  if(plan.motion){outline(plan[active==='start'?'end':'start'],'#70c4e5',true);const a=Geometry.centre(plan.start),b=Geometry.centre(plan.end);ctx.strokeStyle='#70c4e5';ctx.beginPath();ctx.moveTo(box.x+a.x*box.w,box.y+a.y*box.h);ctx.lineTo(box.x+b.x*box.w,box.y+b.y*box.h);ctx.stroke();}
  outline(r,'#f1c27f');if(grid.checked){ctx.strokeStyle='#f1c27f90';ctx.lineWidth=1;for(let i=1;i<=2;i++){ctx.beginPath();ctx.moveTo(sx+rw*i/3,sy);ctx.lineTo(sx+rw*i/3,sy+rh);ctx.moveTo(sx,sy+rh*i/3);ctx.lineTo(sx+rw,sy+rh*i/3);ctx.stroke();}}
  ctx.fillStyle='#f1c27f';for(const [u,v]of [[0,0],[1,0],[0,1],[1,1]])ctx.fillRect(sx+rw*u-6,sy+rh*v-6,12,12);
  const fx=box.x+plan.focus.x*box.w,fy=box.y+plan.focus.y*box.h;ctx.strokeStyle='#ff8a96';ctx.lineWidth=2;ctx.beginPath();ctx.arc(fx,fy,9,0,Math.PI*2);ctx.moveTo(fx-14,fy);ctx.lineTo(fx+14,fy);ctx.moveTo(fx,fy-14);ctx.lineTo(fx,fy+14);ctx.stroke();
 }
 function drawPreview(rect){if(!img||!plan)return;const {ctx,w,h}=surface(preview),a=Geometry.ratio(plan.aspect),pw=Math.min(w,h*a),ph=pw/a;ctx.clearRect(0,0,w,h);ctx.drawImage(img,rect.x*img.naturalWidth,rect.y*img.naturalHeight,rect.w*img.naturalWidth,rect.h*img.naturalHeight,(w-pw)/2,(h-ph)/2,pw,ph);}
 function sync(){if(!plan)return;enabled.checked=plan.enabled;motion.checked=plan.motion;end.disabled=copy.disabled=!plan.motion;start.className=active==='start'?'selected':'';end.className=active==='end'?'selected':'';move.className=mode==='move'?'selected':'';focus.className=mode==='focus'?'selected':'';canvas.style.cursor=mode==='focus'?'crosshair':'grab';const r=plan[active],c=Geometry.centre(r),z=Geometry.fit(plan.sourceRatio,plan.aspect).w/r.w;zoom.input.value=z;zoom.out.textContent=z.toFixed(2)+'×';x.input.value=c.x*100;x.out.textContent=(c.x*100).toFixed(1)+'%';y.input.value=c.y*100;y.out.textContent=(c.y*100).toFixed(1)+'%';message.textContent=!Geometry.inside(plan.focus,plan.start)||(plan.motion&&!Geometry.inside(plan.focus,plan.end))?L.compositionFocus:'';progress.textContent=init.aspect+' · '+(active==='start'?L.cropStart:L.cropEnd);draw();drawPreview(r);}
 function stop(){playing=false;win.cancelAnimationFrame(frame);play.textContent=L.cropPlay;}
 function tick(){if(!playing||closed)return;const t=((win.performance.now()-started)/(init.duration*1000))%1;drawPreview(plan.motion?Geometry.interpolate(plan.start,plan.end,t):plan.start);progress.textContent=(t*init.duration).toFixed(1)+' / '+init.duration+' s';frame=win.requestAnimationFrame(tick);}
 function point(e){const bounds=canvas.getBoundingClientRect(),box=imageBox(bounds.width,bounds.height);return {x:(e.clientX-bounds.left-box.x)/box.w,y:(e.clientY-bounds.top-box.y)/box.h,box};}
 canvas.onpointerdown=e=>{if(!plan||e.button!==0)return;const p=point(e);if(p.x<0||p.x>1||p.y<0||p.y>1)return;stop();canvas.focus();if(mode==='focus'){plan.focus={x:p.x,y:p.y};sync();return;}const r=plan[active];let handle='';for(const [name,u,v]of [['nw',r.x,r.y],['ne',r.x+r.w,r.y],['sw',r.x,r.y+r.h],['se',r.x+r.w,r.y+r.h]])if(Math.hypot((p.x-u)*p.box.w,(p.y-v)*p.box.h)<18)handle=name;if(!handle&&!Geometry.inside(p,r))return;drag={point:p,rect:{...r},handle};canvas.setPointerCapture(e.pointerId);};
 canvas.onpointermove=e=>{if(!drag)return;const p=point(e);plan[active]=drag.handle?Geometry.resize(drag.rect,drag.handle,p,plan.sourceRatio,plan.aspect):Geometry.move(drag.rect,p.x-drag.point.x,p.y-drag.point.y);sync();};
 canvas.onpointerup=canvas.onpointercancel=()=>{drag=null;};canvas.onlostpointercapture=()=>{drag=null;};
 canvas.addEventListener('wheel',e=>{if(!plan)return;e.preventDefault();stop();const p=point(e);plan[active]=Geometry.zoom(plan[active],e.deltaY>0?1.08:1/1.08,plan.sourceRatio,plan.aspect,p);sync();},{passive:false});
 canvas.onkeydown=e=>{if(!plan)return;const step=e.shiftKey?.02:.005,delta={ArrowLeft:[-step,0],ArrowRight:[step,0],ArrowUp:[0,-step],ArrowDown:[0,step]}[e.key];if(delta){e.preventDefault();stop();plan[active]=Geometry.move(plan[active],...delta);sync();}else if(e.key==='+'||e.key==='-'||e.key==='='){e.preventDefault();stop();plan[active]=Geometry.zoom(plan[active],e.key==='-'?1.08:1/1.08,plan.sourceRatio,plan.aspect);sync();}};
 const observer=new win.ResizeObserver(()=>{draw();if(plan&&!playing)drawPreview(plan[active]);});observer.observe(canvas);observer.observe(preview);win.addEventListener('pagehide',()=>{closed=true;stop();observer.disconnect();},{once:true});
 void load();return {close:()=>win.close()};
}

export function mountComposition({node,button,t,getState,persist,renderShots,computed,status}){
 const windows=new Map();
 function open(shot){const project=getState(),key=project.id+':'+shot.id,old=windows.get(key);if(old&&!old.closed){old.focus();return;}const images=[['reference',project.reference],['result',shot.result]].filter(([,image])=>image).map(([source,image])=>({source,...image,key:Geometry.imageKey(image)}));if(!images.length)return;
  const win=window.open('','SceneDNA_Crop_'+shot.id,'popup,width=1500,height=980,resizable=yes,scrollbars=yes');if(!win){status('cropBlocked');return;}windows.set(key,win);const aspect=project.aspect,projectId=project.id;
  const init={title:shot.title,language:project.language,aspect,framing:shot.framing,camera:shot.camera,duration:shot.duration,images,plan:shot.composition?structuredClone(shot.composition):null,stale:!!Geometry.status(project,shot).reason};
  createCompositionEditor(win,init,Object.fromEntries(['cropTitle','cropHelp','cropSource','cropReference','cropResult','cropStart','cropEnd','cropMotion','cropFocus','cropMove','cropCopy','cropSuggested','cropApply','cropCancel','cropPlay','cropStop','cropZoom','cropX','cropY','cropGrid','cropEnabled','cropView','compositionStale','compositionFocus','cropChanged'].map(k=>[k,t(k)])),plan=>{const p=getState(),current=p.shots.find(s=>s.id===shot.id),image=plan.source==='result'?current?.result:p.reference;if(p.id!==projectId||!current||p.aspect!==aspect||!image||Geometry.imageKey(image)!==plan.sourceKey)return t('cropChanged');current.composition=Geometry.validate(plan);persist();renderShots();computed();status('cropSaved');return '';});
 }
 function add(parent,shot){const p=getState(),bar=node('div');bar.className='mini-toolbar';const b=button(t('cropOpen'),()=>open(shot));b.classList.add('crop-open');b.disabled=!p.reference&&!shot.result;b.title=b.disabled?t('cropEmpty'):t('cropHelp');bar.append(b);let seen=false;try{seen=localStorage.getItem('artoftomworks.scene-dna.new.composition')==='seen';}catch{}if(!seen){const badge=button(t('cropNew'),()=>{try{localStorage.setItem('artoftomworks.scene-dna.new.composition','seen');}catch{}for(const el of document.querySelectorAll('.crop-new'))el.remove();},'badge crop-new');badge.setAttribute('aria-label',t('cropDismiss'));bar.append(badge);}if(shot.composition)bar.append(button(t('cropClear'),()=>{delete shot.composition;persist();renderShots();computed();}));parent.append(bar);
  const info=Geometry.status(p,shot);if(info.reason){parent.append(node('p',t('compositionStale')));return;}if(!info.active)return;const views=node('div');views.className='crop-views';for(const which of info.plan.motion?['start','end']:['start']){const box=node('figure'),canvas=node('canvas'),caption=node('figcaption',t(which==='start'?'cropStart':'cropEnd'));canvas.setAttribute('aria-label',t('cropView'));box.append(canvas,caption);views.append(box);const image=new Image();image.onload=()=>{const r=info.plan[which];canvas.width=640;canvas.height=Math.round(640/Geometry.ratio(info.plan.aspect));canvas.getContext('2d').drawImage(image,r.x*image.width,r.y*image.height,r.w*image.width,r.h*image.height,0,0,canvas.width,canvas.height);};image.src=info.image.data;}parent.append(views,node('p',t('cropView')));if(info.plan.motion)parent.append(node('p',t('cropCamera')));
 }
 window.addEventListener('pagehide',()=>{for(const w of windows.values())if(!w.closed)w.close();});return {add,open};
}
